"use client";

import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabase";
import { 
  Trophy, Users, Star, Crown, 
  ArrowUpRight, Loader2, Search, Zap,
  TrendingUp, Award, UserCheck, Mail, Phone, Calendar,
  ListFilter
} from "lucide-react";

export default function WaitlistIntelligencePage() {
  const [waitlistRank, setWaitlistRank] = useState<any[]>([]);
  const [vendorRank, setVendorRank] = useState<any[]>([]);
  const [fullRegistry, setFullRegistry] = useState<any[]>([]); // 🔥 The Master List
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState(""); // Search functionality

  useEffect(() => {
    fetchIntelligence();
  }, []);

  async function fetchIntelligence() {
    setLoading(true);
    
    // 1. Fetch Top Waitlist Recruiters (Leaderboard)
    const { data: waitlistData } = await supabase
      .from('waitlist')
      .select('business_name, email, referral_count, created_at')
      .order('referral_count', { ascending: false })
      .limit(10);

    // 2. Fetch Top Vendor Recruiters (Ambassadors)
    const { data: vendorData } = await supabase
      .from('stores')
      .select('name, referral_count, subscription_plan')
      .order('referral_count', { ascending: false })
      .limit(10);

    // 3. 🔥 Fetch the Master Registry (Everyone)
    const { data: registryData } = await supabase
      .from('waitlist')
      .select('business_name, email, phone, referral_count, created_at')
      .order('created_at', { ascending: false });

    if (waitlistData) setWaitlistRank(waitlistData);
    if (vendorData) setVendorRank(vendorData);
    if (registryData) setFullRegistry(registryData);
    setLoading(false);
  }

  // Filter the registry based on search
  const filteredRegistry = fullRegistry.filter(entry => 
    entry.business_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    entry.email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    entry.phone?.includes(searchTerm)
  );

  if (loading) return (
    <div className="h-96 flex flex-col items-center justify-center gap-4">
      <Loader2 className="animate-spin text-emerald-500" size={40} />
      <p className="text-gray-500 font-black uppercase tracking-widest text-[10px]">Processing Empire Intelligence...</p>
    </div>
  );

  return (
    <div className="space-y-10 animate-in fade-in duration-700 pb-20">
      
      {/* --- PAGE HEADER --- */}
      <div className="flex flex-col md:flex-row justify-between items-end gap-4">
        <div>
          <h2 className="text-3xl font-black text-white uppercase tracking-tighter italic">Growth Intelligence</h2>
          <p className="text-gray-400 text-sm font-medium">Tracking the recruiters building the StoreLink Empire.</p>
        </div>
        <button 
          onClick={fetchIntelligence}
          className="px-6 py-2 bg-gray-900 border border-gray-800 rounded-xl text-[10px] font-black uppercase text-gray-400 hover:text-white transition-all flex items-center gap-2"
        >
          <TrendingUp size={14} /> Refresh Ranks
        </button>
      </div>

      {/* --- LEADERBOARDS GRID --- */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Waitlist Champions */}
        <div className="space-y-6">
          <div className="flex items-center gap-3 px-2">
            <div className="p-2 bg-blue-500/10 text-blue-500 rounded-xl border border-blue-500/20">
              <Users size={20} />
            </div>
            <h3 className="font-black text-xl text-white uppercase tracking-tighter italic">Waitlist Champions</h3>
          </div>
          <div className="bg-gray-900/40 border border-gray-800 rounded-[2.5rem] p-6 backdrop-blur-sm shadow-2xl">
            <div className="space-y-4">
              {waitlistRank.map((user, idx) => (
                <div key={user.email} className="flex items-center justify-between p-4 bg-black/20 rounded-2xl border border-white/5 group hover:border-blue-500/30 transition-all">
                  <div className="flex items-center gap-4">
                    <span className={`text-sm font-black italic ${idx < 3 ? 'text-amber-500' : 'text-gray-600'}`}>#{idx + 1}</span>
                    <div>
                      <p className="text-sm font-bold text-white uppercase tracking-tight">{user.business_name || "New Merchant"}</p>
                      <p className="text-[10px] text-gray-500">{user.email}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-xl font-black text-blue-500 italic">{user.referral_count}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Active Ambassadors */}
        <div className="space-y-6">
          <div className="flex items-center gap-3 px-2">
            <div className="p-2 bg-emerald-500/10 text-emerald-500 rounded-xl border border-emerald-500/20">
              <Crown size={20} />
            </div>
            <h3 className="font-black text-xl text-white uppercase tracking-tighter italic">Active Ambassadors</h3>
          </div>
          <div className="bg-gray-900/40 border border-gray-800 rounded-[2.5rem] p-6 backdrop-blur-sm shadow-2xl">
            <div className="space-y-4">
              {vendorRank.map((store, idx) => (
                <div key={store.name} className="flex items-center justify-between p-4 bg-black/20 rounded-2xl border border-white/5 group hover:border-emerald-500/30 transition-all">
                  <div className="flex items-center gap-4">
                    <span className={`text-sm font-black italic ${idx < 3 ? 'text-amber-500' : 'text-gray-600'}`}>#{idx + 1}</span>
                    <div>
                      <p className="text-sm font-bold text-white uppercase tracking-tight">{store.name}</p>
                      <span className="text-[9px] px-2 py-0.5 bg-gray-800 text-gray-400 rounded-md font-black uppercase">Plan: {store.subscription_plan}</span>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-xl font-black text-emerald-500 italic">{store.referral_count}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* --- 🔥 MASTER WAITLIST REGISTRY (THE NEW SECTION) --- */}
      <div className="space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 px-2">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-amber-500/10 text-amber-500 rounded-xl border border-amber-500/20">
              <ListFilter size={20} />
            </div>
            <div>
              <h3 className="font-black text-xl text-white uppercase tracking-tighter italic">Master Registry</h3>
              <p className="text-[9px] text-gray-500 font-black uppercase tracking-widest">Full Signup Database</p>
            </div>
          </div>
          
          <div className="relative w-full md:w-96">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-500" size={18} />
            <input 
              type="text" 
              placeholder="Search by name, email or phone..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-gray-900 border border-gray-800 rounded-2xl py-3 pl-12 pr-4 text-sm text-white focus:ring-2 focus:ring-emerald-500 outline-none transition-all shadow-xl"
            />
          </div>
        </div>

        <div className="bg-gray-900/40 border border-gray-800 rounded-[2.5rem] overflow-hidden backdrop-blur-sm shadow-2xl">
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead className="bg-black/40 border-b border-gray-800">
                <tr>
                  <th className="px-6 py-5 text-[10px] font-black text-gray-500 uppercase tracking-widest italic">Vendor Identity</th>
                  <th className="px-6 py-5 text-[10px] font-black text-gray-500 uppercase tracking-widest italic">Contact Info</th>
                  <th className="px-6 py-5 text-[10px] font-black text-gray-500 uppercase tracking-widest italic text-center">Score</th>
                  <th className="px-6 py-5 text-[10px] font-black text-gray-500 uppercase tracking-widest italic text-right">Joined Date</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-800/50">
                {filteredRegistry.map((entry) => (
                  <tr key={entry.email} className="group hover:bg-emerald-500/5 transition-colors">
                    <td className="px-6 py-5">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 bg-gray-800 rounded-lg flex items-center justify-center text-gray-500 group-hover:text-emerald-500 transition-colors">
                          <Award size={16} />
                        </div>
                        <p className="text-sm font-black text-white uppercase tracking-tight italic">{entry.business_name || "New Merchant"}</p>
                      </div>
                    </td>
                    <td className="px-6 py-5">
                      <div className="flex flex-col gap-1">
                        <div className="flex items-center gap-2 text-xs text-gray-400 group-hover:text-gray-200 transition-colors">
                          <Mail size={12} className="text-blue-500" /> {entry.email}
                        </div>
                        <div className="flex items-center gap-2 text-xs text-gray-400 group-hover:text-gray-200 transition-colors">
                          <Phone size={12} className="text-emerald-500" /> {entry.phone}
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-5 text-center">
                      <div className="inline-flex items-center justify-center w-8 h-8 rounded-full bg-gray-800 border border-gray-700 text-xs font-black text-blue-400">
                        {entry.referral_count}
                      </div>
                    </td>
                    <td className="px-6 py-5 text-right">
                      <div className="flex items-center justify-end gap-2 text-[10px] font-bold text-gray-600">
                        <Calendar size={12} />
                        {new Date(entry.created_at).toLocaleDateString('en-NG', { day: 'numeric', month: 'short', year: 'numeric' })}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            {filteredRegistry.length === 0 && (
              <div className="p-20 text-center">
                <p className="text-gray-500 font-black uppercase tracking-widest text-xs italic">No matching vendors found.</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* --- FOOTER BANNER --- */}
      <div className="bg-amber-500/5 border border-amber-500/10 p-8 rounded-[2.5rem] flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-amber-500/20 text-amber-500 rounded-2xl flex items-center justify-center">
            <Star size={24} fill="currentColor" />
          </div>
          <div>
            <h4 className="text-white font-black uppercase italic tracking-tight">Alpha Launch Selection</h4>
            <p className="text-gray-400 text-xs">Priority access will be granted to the Top 50 Recruiters across both lists.</p>
          </div>
        </div>
        <button className="px-8 py-4 bg-amber-500 text-black font-black uppercase text-[10px] tracking-widest rounded-2xl hover:scale-105 transition-transform shadow-xl shadow-amber-500/20">
          Prepare Launch Invites
        </button>
      </div>

    </div>
  );
}